def get_total_number_of_sequences(m, n):
    # If n is 1, every element >=1 and <=m qualifies, so there are m sequences
    if n == 1:
        return m
    # Initialize a table to store intermediate results
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    total = 0
    # First item can be any value from 1 to m
    for i in range(1, m + 1):
        dp[1][i] = 1

    # Fill a DP table with the number of valid sequences of length k with max value v
    for k in range(2, n + 1):
        for v in range(1, m + 1):
            for w in range(max(1, v // 2), v):
                dp[k][v] += dp[k - 1][w]

    # The overall number of allowed sequences is the sum for all possible final values
    for v in range(1, m + 1):
        total += dp[n][v]

    return total
