def get_total_number_of_sequences(m, n):
    if n == 1:
        return m

    memo = {}

    def dp(current_length, prev_value):
        if (current_length, prev_value) in memo:
            return memo[(current_length, prev_value)]
        if current_length == 1:
            return 1

        count = 0
        for val in range(max(2 * prev_value, 1), m + 1):
            count += dp(current_length - 1, val)

        memo[(current_length, prev_value)] = count
        return count

    total_sequences = 0
    for start_val in range(1, m + 1):
        total_sequences += dp(n, start_val)

    return total_sequences
