def eulerian_num(n, m):
    """Return the Eulerian number A(n, m), where A(n, 1) = 1 for all n and A(n, m) = (n - m + 1)*A(n-1, m-1) + (m)*A(n-1, m) for other cases."""
    if m == 1 or m == n:
        return 1
    if m == n - 1:
        return 2**n - n - 1
    if m > n or m <= 0 or n <= 0:
        return 0

    # Use the recurrence relation for other cases
    return (n - m + 1) * eulerian_num(n - 1, m - 1) + m * eulerian_num(n - 1, m)
