    if n == 0:
        return 0

    dp_prev = [0] * (m + 1)
    # For length 1, any number from 1 to m is valid
    for num in range(1, m + 1):
        dp_prev[num] = 1

    for _ in range(1, n):
        dp_current = [0] * (m + 1)
        for num in range(1, m + 1):
            if dp_prev[num] > 0:
                start = max(2 * num, 1)
                end = min(2 * num, m) if 2 * num <= m else m
