    """Returns the Eulerian number A(n, m) where 1 ≤ m ≤ n.

    The Eulerian numbers count the number of permutations of n elements
    with exactly m-1 descents. """

    # Handle base cases directly
    if n == 0 and m == 0:
        return 1

    # For fixed m = 1 or m = n (with m starting from 1)
    if m == 1:
        return (2**(n + 1) - n - 2) // (n + 1)
    elif m == n:
        return 1

    # Compute Eulerian numbers using recurrence relation:
    # A(n, m) = (n - m + 1) * A(n - 1, m - 1) + (m) * A(n - 1, m)
    # with base cases A(i, i) = 1 for any i >= 1

    # Initialize table with all zeros
    table = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill base cases: A(i, i) = 1 and A(i, 1) = (2^(i+1) - i - 2)/(i + 1)
    for i in range(n + 1):
        if i == 0 and m == 0:
            continue
        elif i >= m:
            table[i][i] = 1
        if m == 1:
            if i != 0:  # use the formula explicitly for m = 1
                table[i][m] = (2**(i + 1) - i - 2) // (i + 1)

    # Build Pascal-like triangle for recurrence
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if table[i][j] == 0: # We already have base cases
                table[i][j] = (i - j + 1) * table[i - 1][j - 1] + j * table[i - 1][j]

    return table[n][m]
